select plan(22);select has_function('public','get_org_entitlements',array['uuid'],'entitlement RPC exists');select has_function('public','apply_billing_subscription',array['text','text','text','text','uuid','text','text','text','text','text','text','timestamp with time zone','timestamp with time zone','boolean','timestamp with time zone'],'trusted billing sync RPC exists');select has_column('public','invoice_items','recognized_revenue_centavos','invoice lines preserve recognized revenue');select has_column('public','plans','provider_monthly_price_id','provider price configuration exists');
set local role anon;set local "request.jwt.claims"='{"role":"anon"}';select throws_ok($$select * from organization_subscriptions$$,'42501',null,'anon cannot read subscriptions');select throws_ok($$select get_org_entitlements('2c000000-0000-4000-8000-000000000001')$$,'42501',null,'anon cannot read entitlements');
reset role;set local role authenticated;set local "request.jwt.claims"='{"sub":"1c000000-0000-4000-8000-000000000001","role":"authenticated"}';select is(get_org_entitlements('2c000000-0000-4000-8000-000000000001')->>'planId','business','active subscription grants plan');select ok((get_org_entitlements('2c000000-0000-4000-8000-000000000001')->'features'->>'advanced_reports')::boolean,'business grants advanced reports');select throws_ok($$select get_org_entitlements('2c000000-0000-4000-8000-000000000002')$$,'42501','Organization not found','owner A denied Org B entitlements');select throws_ok($$select apply_billing_subscription('stripe','attack','x','x','2c000000-0000-4000-8000-000000000001','pro','cus','sub','active','price','month',now(),now(),false,now())$$,'42501',null,'browser user cannot apply provider event');select throws_ok($$insert into branches(organization_id,name)values('2c000000-0000-4000-8000-000000000001','A3')$$,'P0001','Branch limit reached','branch limit enforced');
reset role;set local role authenticated;set local "request.jwt.claims"='{"sub":"1c000000-0000-4000-8000-000000000003","role":"authenticated"}';select is((select count(*)from organization_subscriptions)::bigint,0::bigint,'manager cannot read owner billing state');select lives_ok($$select get_org_entitlements('2c000000-0000-4000-8000-000000000001')$$,'member can resolve operational entitlements');
reset role;update plans set provider_monthly_price_id='price-pro' where id='pro';set local role service_role;select ok(apply_billing_subscription('stripe','evt-1','customer.subscription.updated','hash','2c000000-0000-4000-8000-000000000001','pro','cus-1','sub-1','active','price-pro','month',now(),now()+interval'1 month',false,now()),'verified provider path applies subscription');select is(apply_billing_subscription('stripe','evt-1','customer.subscription.updated','hash','2c000000-0000-4000-8000-000000000001','pro','cus-1','sub-1','active','price-pro','month',now(),now()+interval'1 month',false,now()),false,'duplicate provider event is idempotent');
reset role;set local role authenticated;set local "request.jwt.claims"='{"sub":"1c000000-0000-4000-8000-000000000001","role":"authenticated"}';select is(get_org_entitlements('2c000000-0000-4000-8000-000000000001')->>'planId','pro','provider event changes effective plan');
reset role;set local role authenticated;set local "request.jwt.claims"='{"sub":"1c000000-0000-4000-8000-000000000002","role":"authenticated"}';select throws_ok($$update organizations set public_page_enabled=true where id='2c000000-0000-4000-8000-000000000002'$$,'P0001','Public page requires an eligible plan','free plan cannot enable paid public page');reset role;set local "request.jwt.claims"='{"sub":"1c000000-0000-4000-8000-000000000002","role":"authenticated"}';select lives_ok($$insert into organization_memberships(organization_id,user_id,role)values('2c000000-0000-4000-8000-000000000002','1c000000-0000-4000-8000-000000000004','cashier')$$,'free plan permits second member');select throws_ok($$insert into organization_memberships(organization_id,user_id,role)values('2c000000-0000-4000-8000-000000000002','1c000000-0000-4000-8000-000000000003','viewer')$$,'P0001','Staff limit reached','free staff limit enforced');
reset role;update plans set provider_monthly_price_id='price-pro' where id='pro';set local role service_role;select ok(apply_billing_subscription('stripe','evt-2','customer.subscription.deleted','hash2','2c000000-0000-4000-8000-000000000001','pro','cus-1','sub-1','cancelled','price-pro','month',now(),now(),false,now()+interval'1 second'),'cancellation event applied');
reset role;set local role authenticated;set local "request.jwt.claims"='{"sub":"1c000000-0000-4000-8000-000000000001","role":"authenticated"}';select is(get_org_entitlements('2c000000-0000-4000-8000-000000000001')->>'planId','free','cancelled subscription falls back to free entitlements');select is((select count(*)from branches where organization_id='2c000000-0000-4000-8000-000000000001')::bigint,2::bigint,'downgrade does not delete existing branches');
select * from finish();rollback;
